<?php
declare(strict_types=1);
require_once __DIR__ . '/conexao.php';
require_once __DIR__ . '/funcoes.php';

$id = filter_input(INPUT_GET, 'id', FILTER_VALIDATE_INT);
if (!$id || $id < 1) redirecionar('index.php');
$stmt = $pdo->prepare('SELECT * FROM produtos WHERE id = :id AND status = :status');
$stmt->execute(['id' => $id, 'status' => 'Ativo']);
$produto = $stmt->fetch();
if (!$produto) { flash('erro', 'Produto não encontrado.'); redirecionar('index.php'); }
$especificacoes = array_filter(array_map('trim', explode('|', (string)($produto['especificacoes'] ?? ''))));
$qtdCarrinho = quantidadeCarrinho();
?>
